const reference=new URLSearchParams(location.search).get('reference'),status=document.querySelector('#payment-status'),button=document.querySelector('#retry');if(reference)document.querySelector('#whatsapp').href='https://wa.me/2348026676582?text='+encodeURIComponent('Hi 23 Lux Nails, I would like to discuss booking '+reference);
async function verify(){button.disabled=true;try{const response=await fetch('/api/payments/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference})}),result=await response.json();if(!response.ok)throw new Error(result.error);status.textContent=result.status==='confirmed'?`Payment verified. Your booking is confirmed. Reference: ${reference}.`:`Payment received. The studio needs to review this booking. Please contact us with reference ${reference}.`;}catch(error){status.textContent=error.message+' You can check again or contact the studio. Do not pay again if you have already been charged.';}finally{button.disabled=false;}}button.onclick=verify;verify();
